interface Cat { meow(): void; }
interface Dog { bark(): void; }

// BUG: returns boolean, so it does NOT narrow at the call site.
function isCat(a: Cat | Dog): boolean {
  return 'meow' in a;
}

function speak(animal: Cat | Dog) {
  if (isCat(animal)) {
    // animal is still Cat | Dog here -> calling meow() is a type error
    animal.meow();
  }
}

speak({ meow: () => console.log('meow') });

solution.code:
interface Cat { meow(): void; }
interface Dog { bark(): void; }

function isCat(a: Cat | Dog): a is Cat {
  return 'meow' in a;
}

function speak(animal: Cat | Dog) {
  if (isCat(animal)) {
    animal.meow(); // animal is Cat here
  } else {
    animal.bark(); // animal is Dog here
  }
}

speak({ meow: () => console.log('meow') });

type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'square'; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.radius ** 2;
    case 'square':
      return shape.side ** 2;
    default: {
      const _exhaustive: never = shape;
      return _exhaustive;
    }
  }
}

console.log(area({ kind: 'circle', radius: 2 }).toFixed(2));
console.log(area({ kind: 'square', side: 3 }));
